const search=document.querySelector('#search'), category=document.querySelector('#category');function filter(){let n=0;document.querySelectorAll('.card').forEach(c=>{const show=c.textContent.toLowerCase().includes(search.value.trim().toLowerCase())&&(!category.value||c.dataset.category===category.value);c.hidden=!show;c.style.display=show?'flex':'none';if(show)n++});document.querySelector('#count').textContent=n+' guide'+(n===1?'':'s');document.querySelector('#empty').hidden=n!==0}search.addEventListener('input',filter);category.addEventListener('change',filter);function calc(){const values=['price','servings','grams'].map(id=>Number(document.getElementById(id).value));document.querySelector('#result').textContent=values.every(v=>Number.isFinite(v)&&v>0)?'$'+(values[0]/(values[1]*values[2])*25).toFixed(2)+' per 25 g protein':'Enter a positive number in every field.'}['price','servings','grams'].forEach(id=>document.getElementById(id).addEventListener('input',calc));calc();